function esc(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]||c))}
function money(v,c='GBP'){if(v==null||v==='')return'—';try{return new Intl.NumberFormat('en-GB',{style:'currency',currency:c}).format(Number(v))}catch{return c+' '+v}}
function msg(t,type=''){const e=$('message');if(e){e.className='small '+type;e.textContent=t||''}}
function busy(b,v,label){if(!b)return;b.disabled=v;if(v&&label){b.dataset.label=b.textContent;b.textContent=label}if(!v&&b.dataset.label){b.textContent=b.dataset.label;delete b.dataset.label}}
function saveSession(v){session=v||null;if(session?.access_token)localStorage.setItem(SESSION_STORAGE,JSON.stringify(session));else localStorage.removeItem(SESSION_STORAGE)}
function restore(){try{const auth=window.tradeflowSubscriberAuth;if(auth?.session?.access_token){session=auth.session;tenantId=auth.tenantId||tenantId;key=auth.key||KEY;return}const s=JSON.parse(localStorage.getItem(SESSION_STORAGE)||'null');if(s?.access_token)session=s}catch{}}
async function api(path,o={}){const h=new Headers(o.headers||{});h.set('apikey',key);h.set('Content-Type','application/json');if(session?.access_token)h.set('Authorization','Bearer '+session.access_token);const r=await fetch(SUPABASE_URL+path,{...o,headers:h});const t=await r.text();let b=null;try{b=t?JSON.parse(t):null}catch{b=t}if(!r.ok)throw Error(b?.message||b?.msg||b?.error_description||b?.error||t||('HTTP '+r.status));return b}
async function rpc(name,body){return api('/rest/v1/rpc/'+name,{method:'POST',body:JSON.stringify(Object.assign({p_tenant_id:tenantId},body||{}))})}
async function storageUpload(path,file){const r=await fetch(SUPABASE_URL+'/storage/v1/object/tradeflow-media/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+(session?.access_token||''),'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});const t=await r.text();let b=null;try{b=t?JSON.parse(t):null}catch{b=t}if(!r.ok)throw Error(b?.message||b?.error||t||'Upload failed');return b}
async function signed(path){const r=await fetch(SUPABASE_URL+'/storage/v1/object/sign/tradeflow-media/'+path,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+(session?.access_token||''),'Content-Type':'application/json'},body:JSON.stringify({expiresIn:86400})});const t=await r.text();let b=null;try{b=t?JSON.parse(t):null}catch{b=t}if(!r.ok)throw Error(b?.message||b?.error||t||'Could not open file');const signedUrl=b?.signedURL;if(!signedUrl)throw Error('Could not create a secure shipping file link.');return signedUrl.startsWith('http')?signedUrl:(signedUrl.startsWith('/storage/v1/')?SUPABASE_URL+signedUrl:(signedUrl.startsWith('/')?SUPABASE_URL+'/storage/v1'+signedUrl:SUPABASE_URL+'/storage/v1/'+signedUrl))}
function stage(r){if(r.purchase_stage&&r.purchase_stage!=='none')return r.purchase_stage;if(r.offer_status==='refused')return'offer_refused';if(r.offer_status==='published')return'offer_ready';if(r.valuation_status==='approved')return'valued';return r.request_status||'submitted'}
function stageLabel(s){return({submitted:'Valuation submitted',under_review:'Under review',valued:'Valuation complete',offer_ready:'Offer sent',awaiting_item:'Awaiting shipping handoff',shipping:'Item on its way',received:'Item received',inspection:'Inspection required',testing:'Testing required',repair:'Repair required',return_pending:'Return required',final_offer_required:'Payment / final offer decision',final_offer_sent:'Final offer received',final_offer_accepted:'Payment required',purchased:'Purchased',offer_refused:'Offer refused'})[s]||s.replaceAll('_',' ')}
function stageClass(s){return['submitted','under_review','valued','offer_ready','awaiting_item','shipping','received','inspection','final_offer_required','final_offer_sent','final_offer_accepted'].includes(s)?'active':''}
function journey(s){const order=['submitted','offer_ready','awaiting_item','shipping','received','inspection','final_offer_required','final_offer_sent','final_offer_accepted','purchased'];let idx=order.indexOf(s);return order.map((x,i)=>({label:stageLabel(x),done:i<idx,active:i===idx})).filter(x=>!['submitted'].includes(x.label.toLowerCase()))}
async function load(){try{if(window.tradeflowSubscriberTenantReady)await window.tradeflowSubscriberTenantReady;else if(window.tradeflowSubscriberAuthReady)await window.tradeflowSubscriberAuthReady;restore();const auth=window.tradeflowSubscriberAuth;if(auth?.session?.access_token){session=auth.session;tenantId=auth.tenantId||tenantId;key=auth.key||KEY}}catch(e){return msg(e.message||String(e),'error')}if(!tenantId)return msg('No subscriber tenant was supplied.','error');if(!session?.access_token)return msg('Sign in to the subscriber dashboard first.','error');try{shippingServices=await api('/rest/v1/tenant_shipping_services?select=service_code,service_name,service_url,enabled,sort_order&tenant_id=eq.'+encodeURIComponent(tenantId)+'&enabled=eq.true&order=sort_order,service_name').catch(()=>[]);const rows=await rpc('subscriber_get_business_workflow');const data=Array.isArray(rows)?rows:[];const ids=data.map(x=>x.buying_item_id).filter(Boolean);let details=[];if(ids.length){details=await Promise.all(ids.map(async id=>{try{const d=await rpc('subscriber_get_buying_item_customer_details',{p_buying_item_id:id});return{id,d}}catch{return{id,d:null}}}))}let values=[];if(ids.length){try{values=await api('/rest/v1/trading_values?select=buying_item_id,cash_price,trade_in_price,amount,currency,status,approved_at&tenant_id=eq.'+encodeURIComponent(tenantId)+'&status=eq.approved&buying_item_id=in.('+ids.join(',')+')&order=approved_at.desc')}catch{values=[]}}let acceptedOffers=[];if(ids.length){try{acceptedOffers=await api('/rest/v1/offers?select=buying_item_id,offer_mode,amount,status,currency,responded_at&tenant_id=eq.'+encodeURIComponent(tenantId)+'&status=eq.accepted&buying_item_id=in.('+ids.join(',')+')&order=responded_at.desc')}catch{acceptedOffers=[]}}let latestOffers=[];if(ids.length){try{latestOffers=await api('/rest/v1/offers?select=buying_item_id,offer_id:id,offer_type,offer_mode,amount,status,currency,published_at,created_at&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=in.('+ids.join(',')+')&order=created_at.desc')}catch{latestOffers=[]}}let shippingRows=[];if(ids.length){try{shippingRows=await api('/rest/v1/buying_item_shipping?select=buying_item_id,shipping_method,shipping_status,shipping_carrier,shipping_service,shipping_tracking_number,shipping_status_updated_at,posted_at,customer_sent_at,shipping_instructions&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=in.('+ids.join(',')+')')}catch{shippingRows=[]}}let returnShippingRows=[];if(ids.length){try{returnShippingRows=await api('/rest/v1/buying_item_return_shipping?select=buying_item_id,return_reason,shipping_status,shipping_carrier,shipping_service,shipping_tracking_number,shipping_tracking_url,shipping_label_storage_path,shipping_label_url,shipping_instructions,shipped_at&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=in.('+ids.join(',')+')')}catch{returnShippingRows=[]}}const byId=Object.fromEntries(details.map(x=>[x.id,x.d]));const valuationByItem={};for(const v of (values||[])){if(!valuationByItem[v.buying_item_id])valuationByItem[v.buying_item_id]=v}const acceptedByItem={};for(const o of (acceptedOffers||[])){if(!acceptedByItem[o.buying_item_id])acceptedByItem[o.buying_item_id]=o}const latestOfferByItem={};for(const o of (latestOffers||[])){if(!latestOfferByItem[o.buying_item_id])latestOfferByItem[o.buying_item_id]=o}const shippingByItem={};for(const x of (shippingRows||[])){if(!shippingByItem[x.buying_item_id])shippingByItem[x.buying_item_id]=x}const returnShippingByItem={};for(const x of (returnShippingRows||[])){if(!returnShippingByItem[x.buying_item_id])returnShippingByItem[x.buying_item_id]=x}current=data.map(r=>Object.assign({},r,{customer:byId[r.buying_item_id]?.customer||null,request_notes:byId[r.buying_item_id]?.request_notes||'',item:byId[r.buying_item_id]?.item||null,valuation:valuationByItem[r.buying_item_id]||null,accepted_offer:acceptedByItem[r.buying_item_id]||null,shipping:shippingByItem[r.buying_item_id]||null,return_shipping:returnShippingByItem[r.buying_item_id]||null,latest_offer:latestOfferByItem[r.buying_item_id]||null,stage:stage(r)}));renderList();if(requestId){const found=current.find(x=>x.request_id===requestId);if(found){openId=found.buying_item_id;renderDetail(found);setTimeout(()=>$('detail-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}}else if(openId){const found=current.find(x=>x.buying_item_id===openId);if(found)renderDetail(found);else closeDetail()}renderCompleted();renderRefused()}catch(e){msg(e.message||String(e),'error')}}
function renderList(){const active=current.filter(r=>r.stage!=='purchased'&&r.stage!=='closed'&&r.stage!=='offer_refused'&&!(r.stage==='return_pending'&&r.return_shipping?.shipping_status==='return_shipped'));const completed=current.filter(r=>r.stage==='purchased');const refused=current.filter(r=>r.stage==='offer_refused');$('request-count').textContent=String(active.length);$('completed-count').textContent=String(completed.length);$('refused-count').textContent=String(refused.length);$('request-list').innerHTML=active.length?'<div class="request-list">'+active.map(r=>{const live=['submitted','offer_ready','awaiting_item','shipping','received','inspection','testing','repair','return_pending','final_offer_required','final_offer_sent','final_offer_accepted'].includes(r.stage);const inspectionCta=r.stage==='received'?'<div class="active-item-action"><button type="button" class="stage-cta" data-inspect="'+esc(r.buying_item_id)+'">Start inspection</button></div>':'';return '<div class="request-card '+(live?'live-stage ':'')+(r.stage==='submitted'?'submitted ':'')+(r.stage==='shipping'?'awaiting-item ':'')+(r.stage==='return_pending'?'requires-action':'')+'" data-open="'+esc(r.buying_item_id)+'"><div class="request-grid"><div><span class="label">Item</span><strong>'+esc(r.title||r.item?.title||'Item')+'</strong><div class="small">'+esc(r.request_reference)+' · '+esc(r.item?.item_reference||'')+'</div></div><div><span class="label">Customer</span><strong>'+esc((r.customer?.first_name||'')+' '+(r.customer?.last_name||''))+'</strong><div class="small">'+esc(r.customer?.email||'')+'</div></div><div><span class="label">Stage</span><span class="stage '+(live?'active':'')+'">'+esc(r.stage==='awaiting_item'&&r.shipping?.shipping_status==='ready_for_customer'?'Awaiting customer dispatch':stageLabel(r.stage))+'</span></div><div><span class="label">Offer</span>'+((r.accepted_offer?.offer_mode)?'<strong>Accepted: '+(r.accepted_offer.offer_mode==='trade_in'?'Trade-in':'Cash')+' '+money(r.accepted_offer.amount,r.currency)+'</strong>':'<strong>'+((r.valuation?.cash_price!=null)?'Cash '+money(r.valuation.cash_price,r.valuation.currency||r.currency):'Cash '+money(r.amount,r.currency))+'</strong>'+(r.valuation?.trade_in_price!=null?'<div><strong>Trade-in '+money(r.valuation.trade_in_price,r.valuation.currency||r.currency)+'</strong></div>':''))+'</div></div>'+inspectionCta+'</div>'}).join('')+'</div>':'<div class="empty">No active buying items.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{openId=b.dataset.open;renderDetail(current.find(x=>x.buying_item_id===openId))});document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();const item=current.find(x=>x.buying_item_id===b.dataset.inspect);if(!item)return;b.disabled=true;b.dataset.label=b.textContent;b.textContent='Starting inspection…';try{await rpc('subscriber_start_buying_item_inspection',{p_buying_item_id:item.buying_item_id});await load();const fresh=current.find(x=>x.buying_item_id===item.buying_item_id)||item;openId=fresh.buying_item_id;renderDetail(fresh);setTimeout(()=>$('detail-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}catch(e){msg(e.message||String(e),'error')}finally{b.disabled=false;if(b.dataset.label){b.textContent=b.dataset.label;delete b.dataset.label}}})}
function renderRefused(){const rows=current.filter(r=>r.stage==='offer_refused');$('refused-list').innerHTML=rows.length?rows.map(r=>'<div class="request-card" data-open="'+esc(r.buying_item_id)+'"><div class="request-grid"><div><span class="label">Item</span><strong>'+esc(r.title||r.item?.title||'Item')+'</strong><div class="small">'+esc(r.request_reference)+' · '+esc(r.item?.item_reference||'')+'</div></div><div><span class="label">Customer</span><strong>'+esc((r.customer?.first_name||'')+' '+(r.customer?.last_name||''))+'</strong><div class="small">'+esc(r.customer?.email||'')+'</div></div><div><span class="label">Status</span><span class="stage">Refused</span></div><div><span class="label">Offer</span><strong>'+((r.valuation?.cash_price!=null)?'Cash '+money(r.valuation.cash_price,r.valuation.currency||r.currency):'Cash '+money(r.amount,r.currency))+'</strong>'+(r.valuation?.trade_in_price!=null?'<div><strong>Trade-in '+money(r.valuation.trade_in_price,r.valuation.currency||r.currency)+'</strong></div>':'')+'</div></div></div>').join(''):'<div class="empty">No refused transactions.</div>';document.querySelectorAll('#refused-list [data-open]').forEach(b=>b.onclick=()=>{openId=b.dataset.open;renderDetail(current.find(x=>x.buying_item_id===openId));document.querySelector('#detail-panel')?.scrollIntoView({behavior:'smooth',block:'start'})})}
function renderCompleted(){const rows=current.filter(r=>r.stage==='purchased');$('completed-list').innerHTML=rows.length?rows.map(r=>'<div class="request-card"><div class="request-grid"><div><span class="label">Item</span><strong>'+esc(r.title||r.item?.title||'Item')+'</strong></div><div><span class="label">Customer</span><strong>'+esc((r.customer?.first_name||'')+' '+(r.customer?.last_name||''))+'</strong></div><div><span class="label">Status</span><span class="stage active">Purchased</span></div><div><span class="label">Acquisition</span><strong>'+esc(r.acquisition_reference||'Created with Inventory')+'</strong></div></div></div>').join(''):'<div class="empty">No completed purchases yet.</div>'}
function renderJourney(s){const order=['Valuation','Offer','Shipping','Received','Inspection','Payment','Inventory','Sale'];const map={Valuation:['submitted','under_review','valued'],Offer:['offer_ready'],Shipping:['awaiting_item','shipping'],Received:['received'],Inspection:['inspection','testing','repair','return_pending','final_offer_required'],Payment:['final_offer_sent','final_offer_accepted'],Inventory:['purchased'],Sale:[]};return '<div class="workflow">'+order.map((name,i)=>{const hit=map[name]?.includes(s);const prior=order.slice(0,i).some(n=>map[n]?.includes(s));return '<div class="workflow-step '+(hit?'active ':'')+(prior?'done':'')+'">'+name+'</div>'}).join('')+'</div>'}
async function renderDetail(r){if(!r)return;const d=$('detail-panel');d.hidden=false;const displayStage=r.stage==='awaiting_item'&&r.shipping?.shipping_status==='ready_for_customer'?'Awaiting customer dispatch':stageLabel(r.stage);$('detail-title').textContent=r.title||r.item?.title||'Item';$('detail-subtitle').textContent=(r.request_reference||'')+' · '+(r.item?.item_reference||'')+' · '+displayStage;const customer=r.customer||{};const latestFinal=r.latest_offer?.offer_type==='final'&&r.latest_offer?.status==='published'?r.latest_offer:null;let html=renderJourney(r.stage);if(latestFinal){html+='<div class="detail-card"><h3>Revised final offer sent</h3><div class="detail-grid"><div class="field"><span class="label">Revised value</span><strong>'+money(latestFinal.amount,latestFinal.currency||'GBP')+'</strong></div><div class="field"><span class="label">Customer response</span><strong>Awaiting customer acceptance or refusal</strong></div></div></div>'}if(r.accepted_offer?.offer_mode){const nextAction={awaiting_item:'Create shipping label and instructions',shipping:'Confirm item received — inspection next',received:'Start inspection',inspection:'Complete inspection',final_offer_required:'Payment / final offer decision',final_offer_sent:'Await customer response',final_offer_accepted:'Send payment'}[r.stage]||'Create shipping label and instructions';html+='<div class="detail-card"><h3>Accepted offer</h3><div class="detail-grid"><div class="field"><span class="label">Customer accepted</span><strong>'+esc(r.accepted_offer.offer_mode==='trade_in'?'Trade-in offer':'Cash offer')+'</strong></div><div class="field"><span class="label">Accepted value</span><strong>'+money(r.accepted_offer.amount,r.currency)+'</strong></div><div class="field"><span class="label">Next action</span><strong>'+esc(nextAction)+'</strong></div></div></div>';}
html+='<div class="detail-card"><h3>Customer</h3><div class="detail-grid"><div class="field"><span class="label">Name</span><strong>'+esc((customer.first_name||'')+' '+(customer.last_name||''))+'</strong></div><div class="field"><span class="label">Email</span><strong>'+esc(customer.email||'—')+'</strong></div><div class="field"><span class="label">Phone</span><strong>'+esc(customer.phone||'—')+'</strong></div><div class="field"><span class="label">Request notes</span><strong>'+esc(r.request_notes||'—')+'</strong></div></div></div>';
const productTitle=String(r.item?.title||r.title||'—').replace(/\s+/g,' ').trim();html+='<div class="detail-card"><h3>Customer supplied item</h3><div class="detail-grid"><div class="field"><span class="label">Product</span><strong>'+esc(productTitle)+'</strong></div></div><div id="supplied-details-'+esc(r.buying_item_id)+'" class="supplied-details"><div class="small">Loading supplied details…</div></div></div><div class="detail-card" id="research-'+esc(r.buying_item_id)+'"><h3>Research evidence</h3><div class="small">Checking available research evidence…</div></div>';
html+='<div class="detail-card"><h3>Actions</h3><div id="action-'+esc(r.buying_item_id)+'"><div class="small">Loading current stage actions…</div></div></div>';
html+='<div class="detail-card"><h3>Photographs</h3><div id="photos-'+esc(r.buying_item_id)+'" class="photos"><div class="small">Loading…</div></div></div>';
$('detail').innerHTML=html;loadPhotos(r.buying_item_id);loadResearch(r.buying_item_id);renderSuppliedDetails(r.buying_item_id,r.item?.description||'');renderActions(r)}
function renderSuppliedDetails(id,description){const e=$('supplied-details-'+id);if(!e)return;const text=String(description||'').replace(/\\n/g,'\n');const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const known=/^(Product type|Manufacturer|Model|Package|Condition|Missing items|Legal right to sell)\s*:\s*(.*)$/i;const items=[];const free=[];for(const line of lines){const m=line.match(known);if(m)items.push({label:m[1],value:m[2]});else free.push(line)}const order=['Product type','Manufacturer','Model','Package','Condition','Missing items','Legal right to sell'];items.sort((a,b)=>order.indexOf(a.label)-order.indexOf(b.label));const blocks=items.map(x=>'<div class="field"><span class="label">'+esc(x.label)+'</span><strong>'+esc(x.value||'—')+'</strong></div>').join('');const descriptionBlock='<div class="field supplied-description"><span class="label">Description</span><strong class="multiline">'+esc(free.join('\n')||'No separate description supplied.')+'</strong></div>';e.innerHTML='<div class="eyebrow">Customer supplied details</div><div class="supplied-detail-grid">'+blocks+'</div>'+descriptionBlock}
async function loadResearch(id){try{const item=await api('/rest/v1/buying_items?select=buying_product_id&tenant_id=eq.'+encodeURIComponent(tenantId)+'&id=eq.'+encodeURIComponent(id));const productId=item?.[0]?.buying_product_id;const e=$('research-'+id);if(!productId){if(e)e.innerHTML='<h3>Research evidence</h3><div class="small">No catalogue product is linked to this item, so no research for this product is available.</div>';return}const rows=await api('/rest/v1/tenant_buying_research?select=evidence_type,source_name,source_url,observed_price,price_currency,item_condition,availability,notes,checked_at&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_product_id=eq.'+encodeURIComponent(productId)+'&order=checked_at.desc');if(!e)return;if(!rows?.length){e.innerHTML='<h3>Research evidence</h3><div class="small">No research for this product.</div>';return}e.innerHTML='<h3>Research evidence</h3><div class="research-list">'+rows.map(x=>'<div class="research-row"><div><strong>'+esc(x.source_name||'Source')+'</strong><div class="small">'+esc(x.evidence_type||'Evidence')+' · '+esc(x.item_condition||'Condition not stated')+'</div></div><div class="research-price">'+(x.observed_price!=null?esc(x.price_currency||'GBP')+' '+Number(x.observed_price).toFixed(2):'—')+'</div><div class="small">'+esc(x.availability||'')+'</div>'+(x.source_url?'<a href="'+esc(x.source_url)+'" target="_blank" rel="noopener">View source</a>':'')+'</div>').join('')+'</div>'}catch(e){const x=$('research-'+id);if(x)x.innerHTML='<h3>Research evidence</h3><div class="small">Research evidence could not be loaded.</div>'}}
async function loadPhotos(id){
 try{
  const e=$('photos-'+id);
  if(!e)return;
  const r=await fetch(SUPABASE_URL+'/functions/v1/subscriber-buying-media?tenant_id='+encodeURIComponent(tenantId)+'&buying_item_id='+encodeURIComponent(id),{
   method:'GET',
   headers:{apikey:key,Authorization:'Bearer '+(session?.access_token||'')}
  });
  const t=await r.text();
  let body=null;try{body=t?JSON.parse(t):null}catch{body=t}
  if(!r.ok)throw Error(body?.error||body?.message||t||('HTTP '+r.status));
  const media=Array.isArray(body?.media)?body.media:[];
  if(!media.length){e.innerHTML='<div class="small">No customer photographs.</div>';return}
  e.innerHTML=media.map(x=>'<a href="'+esc(x.signed_url)+'" target="_blank" rel="noopener"><img src="'+esc(x.signed_url)+'" alt="'+esc(x.original_filename||'Customer photo')+'"></a>').join('');
 }catch(err){
  const e=$('photos-'+id);
  if(e)e.innerHTML='<div class="small error">Photographs could not be opened: '+esc(err?.message||'Secure photo access failed.')+'</div>';
 }
}
function bindActionButtons(){
  if(window.__tradeflowBuyingActionDelegation)return;
  window.__tradeflowBuyingActionDelegation=true;
  document.addEventListener('click',async ev=>{
    const b=ev.target.closest('[data-act]');
    if(!b||b.dataset.act==='final')return;
    ev.preventDefault();
    ev.stopPropagation();
    const status=$('final-action-status-'+b.dataset.id);
    if(b.dataset.act==='final'&&status)status.textContent='';
    try{
      await action(b.dataset.act,b.dataset.id,b);
    }catch(err){
      msg(err?.message||String(err),'error');
    }
  },true);
}
function renderActions(r){const e=$('action-'+r.buying_item_id);if(!e)return;const id=r.buying_item_id,s=r.stage;let h='';
if(s==='received'){h='<div class="green-block"><strong>Item received</strong><p class="small">The physical item has been received. Start the inspection before creating the final offer.</p><div class="actions"><button data-inspect="'+id+'">Start inspection</button></div></div>'}
else if(s==='inspection'){h='<div class="green-block"><strong>Inspection and offer decision</strong><p class="small">Confirm the condition and choose what happens next. You can accept the original value, send the item for testing, send it for repair, refuse the purchase, or make a counter offer based on the inspected condition.</p><div class="two"><label>Condition<select id="inspect-condition-'+id+'"><option value="">Select…</option><option value="poor">Poor</option><option value="good">Good</option><option value="very_good">Very Good</option><option value="excellent">Excellent</option><option value="opened">Opened</option><option value="never_used">Never Used</option><option value="sealed">Sealed</option></select></label><label>Decision<select id="inspect-outcome-'+id+'"><option value="accepted">Accept original offer</option><option value="counter_offer">Make a counter offer</option><option value="testing_required">Send for testing</option><option value="repair_required">Send for repair</option><option value="refused">Refuse purchase</option></select></label></div><label style="display:block;margin-top:10px">Counter offer value (only if making a counter offer)<input id="inspect-counter-'+id+'" type="number" min="0" step="0.01" placeholder="Enter new value"></label><label style="display:block;margin-top:10px"><input id="inspect-description-'+id+'" type="checkbox"> Customer description confirmed</label><label style="display:block;margin-top:8px"><input id="inspect-condition-confirm-'+id+'" type="checkbox"> Inspected condition confirmed</label><label style="display:block;margin-top:8px"><input id="inspect-mismatch-'+id+'" type="checkbox"> Condition not as described</label><label style="display:block;margin-top:10px">Notes<textarea id="inspect-notes-'+id+'" rows="3"></textarea></label><div class="actions"><button type="button" data-act="inspect" data-id="'+id+'">Complete inspection decision</button></div></div>'}
else if(s==='return_pending'){const x=r.return_shipping||{};if(x.shipping_status==='return_shipped'){h='<div class="green-block"><strong>Return shipped to customer</strong><p class="small">The purchase was refused because the item condition was not as described. The return has been shipped to the customer.</p><div class="detail-grid"><div class="field"><span class="label">Reason</span><strong>'+esc(x.return_reason||'Condition not as described.')+'</strong></div><div class="field"><span class="label">Tracking</span><strong>'+esc(x.shipping_tracking_number||'—')+'</strong></div><div class="field"><span class="label">Service</span><strong>'+esc(x.shipping_service||x.shipping_carrier||'—')+'</strong></div></div></div>'}else{const services=shippingServices||[];const providerCards=services.length?services.map(v=>'<div class="field" style="margin-top:8px"><div><strong>'+esc(v.service_name)+'</strong></div><div class="actions"><a href="'+esc(v.service_url)+'" target="_blank" rel="noopener" class="button">Open '+esc(v.service_name)+'</a><button type="button" data-use-return-service="1" data-id="'+id+'" data-service-name="'+esc(v.service_name)+'" data-service-url="'+esc(v.service_url)+'">Use this service</button></div></div>').join(''):'<div class="notice">No preferred shipping services have been selected. Open Shipping Settings and tick the services you use.</div>';h='<div class="green-block"><strong>Return item to customer</strong><p class="small">The purchase has been refused and requires action. Book the return with one of your preferred shipping services, return the physical item to the customer, then enter the tracking number below.</p><div class="field"><strong>Preferred return shipping services</strong>'+providerCards+'</div><div class="two" style="margin-top:12px"><label>Carrier<input id="return-carrier-'+id+'"></label><label>Service<input id="return-service-'+id+'"></label><label>Tracking number<input id="return-tracking-'+id+'"></label><label>Tracking URL<input id="return-tracking-url-'+id+'" placeholder="https://..."></label></div><label style="display:block;margin-top:10px">Instructions<textarea id="return-instructions-'+id+'" rows="3">Your item has been refused because the inspected condition did not match the condition described when you submitted it. The item is being returned to you.</textarea></label><div class="actions"><button type="button" data-returnship="1" data-id="'+id+'">Send tracking information to customer</button></div><div id="return-action-status-'+id+'" class="small" style="margin-top:8px"></div></div>'}}else if(s==='testing'||s==='repair'){const followType=s==='testing'?'Testing':'Repair';h='<div class="green-block"><strong>'+followType+' required</strong><p class="small">The item has been sent to '+followType.toLowerCase()+'. Complete that work, then return to the inspection and offer decision before proceeding to payment.</p><label style="display:block;margin-top:10px">Notes<textarea id="followup-notes-'+id+'" rows="3"></textarea></label><div class="actions"><button type="button" data-act="followup" data-id="'+id+'">Complete '+followType.toLowerCase()+' &amp; return to inspection</button><button type="button" data-act="followup-refuse" data-id="'+id+'">Refuse purchase</button></div></div>'}
else if(s==='final_offer_required'){const amount=Number(r.accepted_offer?.amount);const suggested=Number.isFinite(amount)?amount:'';const mode=r.accepted_offer?.offer_mode==='trade_in'?'trade_in':'cash';const paymentText=mode==='trade_in'?'Add '+money(suggested,r.accepted_offer?.currency||'GBP')+' to customer credit':'Confirm payment sent';h='<div class="green-block"><strong>Payment / final offer decision</strong><p class="small">Inspection is complete. If the accepted value is unchanged, complete payment using the original offer. Only send a revised final offer if the value has changed.</p><div class="field"><span class="label">Accepted value</span><strong>'+money(suggested,r.accepted_offer?.currency||'GBP')+'</strong><div class="actions"><button type="button" data-act="refuse" data-id="'+id+'">Refuse</button></div><div id="post-inspection-payment-'+id+'" class="small" style="margin-top:10px"></div><label style="display:block;margin-top:12px">Revised final offer value<input id="final-'+id+'" type="number" min="0" step="0.01" placeholder="Only enter this if the value has changed"></label><label style="display:block;margin-top:10px">Notes<textarea id="final-notes-'+id+'" rows="2"></textarea></label><div id="final-action-status-'+id+'" class="small" style="margin-top:8px"></div><div class="actions"><button type="button" data-act="final" data-id="'+id+'">Send revised final offer</button></div></div>';if(mode==='cash')setTimeout(()=>loadPostInspectionPayment(id),0)}
else if(s==='final_offer_sent'){h='<div class="notice"><strong>Final offer received by customer</strong><p class="small">Wait for the customer to accept or refuse the final offer.</p></div>'}
else if(s==='final_offer_accepted'){h='<div class="green-block"><strong>Payment required</strong><div id="payment-'+id+'" class="small">Checking customer bank details…</div></div>';setTimeout(()=>loadPayment(id),0)}
else if(s==='purchased'){h='<div class="green-block"><strong>Purchased</strong><p class="small">Payment has been recorded and the physical item has been created in Inventory. Continue from Inventory → Selling.</p></div>'}
else if(s==='awaiting_item'){h=shippingHtml(r)}
else if(s==='shipping'){h=shippingSentHtml(r)}
else if(s==='submitted'||s==='under_review'){
 h='<div class="green-block"><strong>Valuation required</strong><p class="small">Review the customer-supplied item and submit a valuation to create the customer offer.</p><div id="valuation-result-'+id+'"></div><div id="manual-valuation-'+id+'" style="display:none;margin-top:12px"><div class="two"><label>Cash valuation<input id="manual-cash-'+id+'" type="number" min="0" step="0.01" placeholder="0.00"></label><label>Trade-in valuation<input id="manual-trade-'+id+'" type="number" min="0" step="0.01" placeholder="0.00"></label></div><div class="actions"><button type="button" data-act="manual-offer" data-id="'+id+'">Approve valuation &amp; send offer</button></div></div><div id="valuation-check-'+id+'" class="actions"><button type="button" data-act="value" data-id="'+id+'">Check valuation</button><button type="button" data-act="manual-toggle" data-id="'+id+'">Enter manual valuation</button><button type="button" data-act="refuse-valuation" data-id="'+id+'">Refuse valuation</button></div></div>'
}
else if(s==='offer_ready'){h='<div class="green-block"><strong>Offer sent</strong><p class="small">The cash and trade-in offer has been sent to the customer. You can still cancel and refuse the purchase before the item is received.</p><div class="actions"><button type="button" data-act="refuse-valuation" data-id="'+id+'">Cancel and refuse purchase</button></div></div>'}
else if(s==='valued'){h='<div class="green-block"><strong>Customer offer</strong><p class="small">Enter the offer values and send them to the customer, or refuse the transaction before an offer is sent.</p><div class="actions"><button type="button" data-act="offer" data-id="'+id+'">Send cash &amp; trade-in offer</button><button type="button" data-act="refuse-valuation" data-id="'+id+'">Refuse purchase</button></div></div>'}
else {h='<div class="notice"><strong>'+esc(stageLabel(s))+'</strong><p class="small">Review this item and continue the current workflow stage.</p></div>'}
e.innerHTML=h;bindActionButtons();const finalButton=e.querySelector('[data-act="final"]');if(finalButton){finalButton.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();const status=$('final-action-status-'+id);if(status)status.textContent='';try{await action('final',id,finalButton)}catch(err){if(status)status.textContent=err.message||String(err)}}}e.querySelectorAll('[data-inspect]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();const item=current.find(x=>x.buying_item_id===b.dataset.inspect);if(!item)return;busy(b,true,'Starting inspection…');try{await rpc('subscriber_start_buying_item_inspection',{p_buying_item_id:item.buying_item_id});msg('Inspection started.','success');await load();const fresh=current.find(x=>x.buying_item_id===item.buying_item_id)||item;openId=fresh.buying_item_id;renderDetail(fresh);setTimeout(()=>$('detail-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}catch(err){msg(err.message||String(err),'error')}finally{busy(b,false)}}});const returnButton=e.querySelector('[data-returnship]');if(returnButton&&!returnButton.dataset.bound){returnButton.dataset.bound='1';returnButton.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();await shipReturn(id,returnButton)}}}
function shippingDetailsHtml(r,title,copy,button){const id=r.buying_item_id,x=r.shipping||{};const date=x.customer_sent_at||x.posted_at||x.shipping_status_updated_at;const details='<div class="detail-grid" style="margin:12px 0 0"><div class="field"><span class="label">Date shipped</span><strong>'+esc(date?new Date(date).toLocaleString('en-GB'):'—')+'</strong></div><div class="field"><span class="label">Shipping service</span><strong>'+esc(x.shipping_service||x.shipping_carrier||'—')+'</strong></div><div class="field"><span class="label">Tracking number</span><strong>'+esc(x.shipping_tracking_number||'—')+'</strong></div><div class="field"><span class="label">Carrier</span><strong>'+esc(x.shipping_carrier||'—')+'</strong></div></div>';return '<div class="green-block"><strong>'+esc(title)+'</strong><p class="small">'+esc(copy)+'</p>'+details+(button?'<div class="actions"><button data-act="received" data-id="'+id+'">Confirm item received</button><button type="button" data-act="refuse-valuation" data-id="'+id+'">Refuse purchase</button></div>':'')+'<p class="small" style="margin-top:10px"><strong>Next step:</strong> Inspection</p></div>'}
function shippingSentHtml(r){return shippingDetailsHtml(r,'Awaiting item','The shipping label and instructions have been supplied to the customer. The customer has confirmed dispatch; await the physical item before confirming receipt.',true)}
function shippingReceivedHtml(r){return shippingDetailsHtml(r,'Item received','The physical item has been received. The next step is to inspect the item.',false)}
async function applyValuationResult(id,v,prepareOffer){const box=$('valuation-result-'+id);const manual=$('manual-valuation-'+id);const check=$('valuation-check-'+id);if(v.mode==='automatic'||v.mode==='manual_override'){const cash=Number.isFinite(Number(v.amount))?Number(v.amount):null;const trade=Number.isFinite(Number(v.trade_in_amount))?Number(v.trade_in_amount):null;if(box)box.innerHTML='<strong>'+esc(v.mode==='manual_override'?'Manual valuation configured':'Automatic valuation available')+'</strong><div class="two" style="margin-top:10px"><div><span class="label">Cash offer</span><strong>'+money(cash)+'</strong></div><div><span class="label">Trade-in offer</span><strong>'+money(trade)+'</strong></div></div><div class="small" style="margin-top:8px">'+esc(v.reason||'Catalogue valuation configured.')+'</div><div class="actions"><button type="button" data-act="manual-toggle" data-id="'+id+'">Use manual override</button><button type="button" data-act="refuse-valuation" data-id="'+id+'">Refuse valuation</button></div>';if(manual){manual.style.display='none';manual.innerHTML='<div class="two"><label>Cash valuation<input id="manual-cash-'+id+'" type="number" min="0" step="0.01" placeholder="0.00"></label><label>Trade-in valuation<input id="manual-trade-'+id+'" type="number" min="0" step="0.01" placeholder="0.00"></label></div><label style="display:block;margin-top:10px">Notes<textarea id="manual-notes-'+id+'" rows="2"></textarea></label><div class="actions"><button type="button" data-act="manual-offer" data-id="'+id+'">Approve manual valuation &amp; send offer</button><button type="button" data-act="manual-cancel" data-id="'+id+'">Cancel</button><span id="valuation-action-status-'+id+'" class="small"></span></div>'}if(check)check.style.display='none';bindActionButtons();if(prepareOffer)await createInitialOffer(id,v)}else{if(box)box.innerHTML='<strong>Manual valuation required</strong><div class="small" style="margin-top:6px">'+esc(v.reason==='no_research_for_selected_reference'||v.reason==='no_research_for_uk_new'?'No research for this product — manual valuation required.':(v.reason||'No automatic valuation is available.'))+'</div><div class="actions"><button type="button" data-act="refuse-valuation" data-id="'+id+'">Refuse valuation</button></div>';if(manual)manual.style.display='block';if(check)check.style.display='none';bindActionButtons(document)}}
async function action(type,id,b){busy(b,true,'Working…');try{
if(type==='value'){const v=await rpc('calculate_buying_item_valuation',{p_buying_item_id:id});await applyValuationResult(id,v,true);if(v.mode!=='automatic'&&v.mode!=='manual_override'){busy(b,false);return}}
else if(type==='manual-toggle'){const m=$('manual-valuation-'+id);const check=$('valuation-check-'+id);if(m){m.style.display=m.style.display==='none'||!m.style.display?'block':'none';if(m.style.display==='block'&&check)check.style.display='none'}return}
else if(type==='manual-cancel'){const m=$('manual-valuation-'+id);if(m)m.style.display='none';return}
else if(type==='refuse-valuation'){const status=$('valuation-action-status-'+id);if(status)status.textContent='Refusing valuation…';await rpc('subscriber_refuse_buying_item_valuation',{p_buying_item_id:id,p_notes:'Valuation refused from Buying dashboard.'});if(status)status.textContent='Valuation refused.';msg('Valuation refused and transaction closed.','success')}
else if(type==='offer'){const cash=parseFloat($('cash-'+id)?.value),trade=parseFloat($('trade-'+id)?.value);if(!Number.isFinite(cash)&&!Number.isFinite(trade))throw Error('Enter a cash offer or trade-in offer.');await createOffer(id,cash,trade)}
else if(type==='manual-offer'){const cash=parseFloat($('manual-cash-'+id)?.value),trade=parseFloat($('manual-trade-'+id)?.value);if(!Number.isFinite(cash)&&!Number.isFinite(trade))throw Error('Enter a cash valuation or trade-in valuation.');const status=$('valuation-action-status-'+id);if(status)status.textContent='Sending manual valuation…';await rpc('subscriber_create_manual_buying_valuation',{p_buying_item_id:id,p_cash_price:Number.isFinite(cash)?cash:null,p_trade_in_price:Number.isFinite(trade)?trade:null,p_notes:$('manual-notes-'+id)?.value.trim()||null});if(status)status.textContent='Manual valuation approved and offer sent.';msg('Manual valuation approved and offer sent to the customer.','success')}
else if(type==='received'){await rpc('subscriber_mark_buying_item_received',{p_buying_item_id:id});msg('Item received. Inspection is now available.','success');const item=current.find(x=>x.buying_item_id===id);if(item){item.purchase_stage='received';item.stage='received';if(item.shipping)item.shipping.shipping_status='received';renderDetail(item)}busy(b,false);return}
else if(type==='inspect'){const condition=$('inspect-condition-'+id)?.value,outcome=$('inspect-outcome-'+id)?.value;if(!condition)throw Error('Select the inspected condition.');const mismatch=Boolean($('inspect-mismatch-'+id)?.checked);if(!$('inspect-condition-confirm-'+id).checked)throw Error('Confirm the inspected condition before completing the inspection.');if(outcome==='refused'&&!mismatch)throw Error('Tick “Condition not as described” to refuse the purchase.');if(outcome!=='refused'&&!$('inspect-description-'+id).checked)throw Error('Confirm that the item matches the customer description before completing the inspection.');if(outcome==='counter_offer'){const amount=parseFloat($('inspect-counter-'+id)?.value);if(!Number.isFinite(amount))throw Error('Enter the counter offer value.');const accepted=Number(current.find(x=>x.buying_item_id===id)?.accepted_offer?.amount);if(Number.isFinite(accepted)&&amount===accepted)throw Error('The counter offer must be different from the accepted value.');await rpc('subscriber_complete_buying_item_inspection',{p_buying_item_id:id,p_condition_grade:condition,p_passed:true,p_outcome:'accepted',p_notes:($('inspect-notes-'+id).value.trim()||'')+' Counter offer proposed at '+amount.toFixed(2)+'.',p_metadata:{customer_description_confirmed:true,condition_confirmed:true,counter_offer:true}});await rpc('subscriber_publish_final_offer',{p_buying_item_id:id,p_amount:amount,p_notes:$('inspect-notes-'+id).value.trim()||null});msg('Inspection completed and counter offer sent to the customer.','success')}else{await rpc('subscriber_complete_buying_item_inspection',{p_buying_item_id:id,p_condition_grade:condition,p_passed:outcome==='accepted',p_outcome:outcome,p_notes:$('inspect-notes-'+id).value.trim()||null,p_metadata:{customer_description_confirmed:outcome==='refused'?false:true,condition_confirmed:true,condition_not_as_described:mismatch}});msg(outcome==='testing_required'?'Item sent for testing.':outcome==='repair_required'?'Item sent for repair.':outcome==='refused'?'Purchase refused — return to customer is now required.':'Inspection completed.','success')}}
else if(type==='followup'||type==='followup-refuse'){const item=current.find(x=>x.buying_item_id===id);const followType=item?.stage==='testing'?'testing':item?.stage==='repair'?'repair':null;if(!followType)throw Error('This item is not in a testing or repair stage.');if(type==='followup-refuse'){await rpc('subscriber_complete_buying_item_followup',{p_buying_item_id:id,p_followup_type:followType,p_outcome:'refused',p_notes:$('followup-notes-'+id)?.value.trim()||'Purchase refused.'});msg('Purchase refused.','success')}else{await rpc('subscriber_complete_buying_item_followup',{p_buying_item_id:id,p_followup_type:followType,p_outcome:'completed',p_notes:$('followup-notes-'+id)?.value.trim()||null});msg((followType==='testing'?'Testing':'Repair')+' completed. Item returned to inspection and offer decision.','success')}}
else if(type==='final'){const amount=parseFloat($('final-'+id)?.value);const accepted=Number(current.find(x=>x.buying_item_id===id)?.accepted_offer?.amount);if(!Number.isFinite(amount))throw Error('Enter the revised trade-in value.');if(Number.isFinite(accepted)&&amount===accepted)throw Error('The value is unchanged. Add the accepted amount to customer credits instead of sending a final offer.');await rpc('subscriber_publish_final_offer',{p_buying_item_id:id,p_amount:amount,p_notes:$('final-notes-'+id)?.value.trim()||null});msg('Revised final offer sent to the customer.','success')}
else if(type==='credit'){await rpc('subscriber_credit_trade_in',{p_buying_item_id:id});msg('Trade-in credit added to the customer account. Inventory item created.','success')}
else if(type==='refuse'){await rpc('subscriber_refuse_after_inspection',{p_buying_item_id:id,p_notes:$('final-notes-'+id)?.value.trim()||null});msg('Trade-in refused and closed.','success')}
else if(type==='pay'){const ref=$('payment-ref-'+id)?.value.trim();const method=$('payment-method-'+id)?.value.trim()||'Bank transfer';if(!ref)throw Error('Enter the payment reference.');await rpc('subscriber_complete_purchase',{p_buying_item_id:id,p_payment_method:method,p_payment_reference:ref,p_payment_notes:null});msg('Payment recorded. Inventory item created.','success')}
else if(type==='request-bank-details'){const status=$('payment-bank-request-status-'+id);if(status)status.textContent='Sending message…';const result=await rpc('subscriber_request_customer_bank_details',{p_buying_item_id:id});if(result?.sent){if(status)status.textContent='Message sent to the customer. Ask them to add their bank details in My Details.';msg('Bank details request sent to the customer.','success')}else{const message=result?.message||'The bank details request could not be sent.';if(status)status.textContent=message;throw Error(message)}}
else if(type==='pay-unconfirmed'){await loadPostInspectionPayment(id)}
await load();const r=current.find(x=>x.buying_item_id===id);if(r)renderDetail(r)
}catch(e){const errorText=e.message||String(e);msg(errorText,'error');if(type==='pay'||type==='final'){const status=$(type==='pay'?'payment-action-status-'+id:'final-action-status-'+id);if(status)status.textContent=errorText;}}finally{busy(b,false)}}
async function createOffer(id,cash,trade){const vals=await api('/rest/v1/trading_values?select=id,status,method&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=eq.'+encodeURIComponent(id)+'&status=eq.approved&order=approved_at.desc&limit=1');let v=vals?.[0];if(!v){const amount=Number.isFinite(cash)?cash:trade;const rows=await api('/rest/v1/trading_values',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({tenant_id:tenantId,buying_item_id:id,method:'manual',status:'draft',amount,currency:'GBP',cash_price:Number.isFinite(cash)?cash:null,trade_in_price:Number.isFinite(trade)?trade:null,calculated_at:new Date().toISOString(),notes:'Manual valuation',metadata:{source:'new_buying_workflow'}})});v=Array.isArray(rows)?rows[0]:rows;await transition('trading_value',v.id,'draft','approved','Manual valuation approved.')}await createInitialOffer(id,{cash,trade_in:trade,mode:Number.isFinite(cash)?'cash':'trade_in'},v)}
async function createInitialOffer(id,value,valuationOverride){const existing=await api('/rest/v1/offers?select=id,status,offer_mode,amount&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=eq.'+encodeURIComponent(id)+'&offer_type=eq.initial&order=created_at.desc&limit=1');if(existing?.[0]&&['published','accepted'].includes(existing[0].status)){await rpc('subscriber_mark_buying_item_offer_ready',{p_buying_item_id:id,p_notes:'Initial offer already exists; buying item marked offer ready.'});return existing[0]}const cash=Number.isFinite(Number(value?.cash))?Number(value.cash):Number.isFinite(Number(value?.amount))?Number(value.amount):null;const trade=Number.isFinite(Number(value?.trade_in_amount))?Number(value.trade_in_amount):Number.isFinite(Number(value?.trade_in))?Number(value.trade_in):null;const amount=Number.isFinite(cash)?cash:trade;if(!Number.isFinite(amount))throw Error('No offer amount is available.');let v=valuationOverride;if(!v){const vals=await api('/rest/v1/trading_values?select=id,status,cash_price,trade_in_price,amount&tenant_id=eq.'+encodeURIComponent(tenantId)+'&buying_item_id=eq.'+encodeURIComponent(id)+'&status=eq.approved&order=approved_at.desc&limit=1');v=vals?.[0]}if(!v)throw Error('No approved valuation exists.');const rows=await api('/rest/v1/offers',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({tenant_id:tenantId,buying_item_id:id,trading_value_id:v.id,offer_reference:'OF-'+crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase(),offer_type:'initial',offer_mode:Number.isFinite(cash)?'cash':'trade_in',status:'draft',amount,currency:'GBP',created_by:session.user.id})});const o=Array.isArray(rows)?rows[0]:rows;await transition('offer',o.id,'draft','published','Initial offer published from the unified buying workflow.');await rpc('subscriber_mark_buying_item_offer_ready',{p_buying_item_id:id,p_notes:'Initial offer published from the Buying dashboard.'});return o}
async function transition(entityType,entityId,from,to,notes){return rpc('transition_workflow_entity',{p_entity_type:entityType,p_entity_id:entityId,p_expected_from:from,p_to_status:to,p_notes:notes||null,p_metadata:{source:'unified_buying_workflow'}})}
function shippingHtml(r){const id=r.buying_item_id,x=r.shipping||{};if(x.shipping_status==='ready_for_customer'){return '<div class="green-block"><strong>Shipping label sent — awaiting customer dispatch</strong><p class="small">The shipping label and instructions have been sent to the customer. No further shipping setup is required from you at this stage.</p><div class="detail-grid" style="margin:12px 0"><div class="field"><span class="label">Shipping service</span><strong>'+esc(x.shipping_service||x.shipping_carrier||'—')+'</strong></div><div class="field"><span class="label">Tracking number</span><strong>'+esc(x.shipping_tracking_number||'—')+'</strong></div><div class="field"><span class="label">Label status</span><strong>Ready for customer</strong></div><div class="field"><span class="label">Next step</span><strong>Customer sends the item</strong></div></div><div class="notice"><strong>Waiting for the customer</strong><p class="small">The customer can now open or print the label and hand the parcel to the courier. When the customer confirms dispatch, this item will move to <strong>Awaiting receipt</strong>.</p></div><div class="actions"><button type="button" data-act="refuse-valuation" data-id="'+id+'">Cancel and refuse purchase</button></div></div>'}const services=shippingServices||[];const providerCards=services.length?services.map(x=>'<div class="field" style="margin-top:8px"><div><strong>'+esc(x.service_name)+'</strong></div><div class="small">'+esc(x.service_url)+'</div><div class="actions"><a href="'+esc(x.service_url)+'" target="_blank" rel="noopener" class="button">Open '+esc(x.service_name)+'</a><button type="button" data-use-service="1" data-id="'+id+'" data-service-name="'+esc(x.service_name)+'" data-service-url="'+esc(x.service_url)+'">Use this service</button></div></div>').join(''):'<div class="notice">No preferred shipping services have been selected. Open Shipping Settings and tick the services you use.</div>';return '<div class="green-block"><strong>Create shipping label and customer handoff</strong><p class="small">Open your preferred shipping service, create and pay for the shipment directly with the provider, then return here and upload the label or QR code.</p><div class="field"><strong>Preferred shipping services</strong>'+providerCards+'</div><div class="field" style="margin-top:12px"><strong>Shipping label and customer handoff</strong><input id="manual-file-'+id+'" type="file" accept="application/pdf,image/png,image/jpeg"><label>QR code (optional)<input id="manual-qr-'+id+'" type="file" accept="image/png,image/jpeg,application/pdf"></label><label>Carrier<input id="carrier-'+id+'"></label><label>Service<input id="service-'+id+'"></label><label>Tracking number<input id="tracking-'+id+'"></label><label>Instructions<textarea id="instructions-'+id+'" rows="3">Send the item using the shipping label provided. Confirm when it has been handed to the courier.</textarea></label><input id="shipping-service-url-'+id+'" type="hidden"><div class="actions"><button data-ship="manual" data-id="'+id+'">Send shipping instructions to customer</button></div></div></div>'}
async function shipAction(type,id,b){busy(b,true,'Working…');try{if(type==='manual'){const file=$('manual-file-'+id)?.files?.[0];const qr=$('manual-qr-'+id)?.files?.[0];let path=null,qrPath=null;if(file){if(file.size>10*1024*1024)throw Error('Shipping label must be 10 MB or smaller.');const ext=(file.name.split('.').pop()||'pdf').toLowerCase();path=tenantId+'/buying-items/'+id+'/shipping-label-'+Date.now()+'.'+ext;await storageUpload(path,file)}if(qr){if(qr.size>10*1024*1024)throw Error('QR code must be 10 MB or smaller.');const ext=(qr.name.split('.').pop()||'png').toLowerCase();qrPath=tenantId+'/buying-items/'+id+'/shipping-qr-'+Date.now()+'.'+ext;await storageUpload(qrPath,qr)}if(!path&&!qrPath)throw Error('Upload the shipping label or QR code before sending the shipping instructions.');await rpc('subscriber_publish_buying_item_shipping_handoff',{p_buying_item_id:id,p_shipping_method:'subscriber_override',p_shipping_label_url:null,p_shipping_label_storage_path:path,p_shipping_qr_url:null,p_shipping_qr_storage_path:qrPath,p_shipping_carrier:$('carrier-'+id).value.trim()||null,p_shipping_service:$('service-'+id).value.trim()||null,p_shipping_tracking_number:$('tracking-'+id).value.trim()||null,p_shipping_instructions:$('instructions-'+id).value.trim()||null,p_shipping_provider:$('carrier-'+id).value.trim()||null,p_shipping_provider_connection_id:null,p_shipping_service_url:$('shipping-service-url-'+id).value.trim()||null});msg('Shipping instructions sent to the customer.','success');await load();const r=current.find(x=>x.buying_item_id===id);if(r)renderDetail(r)}}catch(e){msg(e.message||String(e),'error')}finally{busy(b,false)}}
async function loadPostInspectionPayment(id){try{const p=await rpc('subscriber_get_buying_item_payment_details',{p_buying_item_id:id});const e=$('post-inspection-payment-'+id);if(!e)return;if(!p.bank_details_received){e.innerHTML='<div class="notice"><strong>Payment cannot be completed yet</strong><p>Customer bank details are not on record. Ask the customer to add their bank details in <strong>My Details</strong> in the Customer Portal.</p><div id="payment-bank-request-status-'+id+'" class="small" style="margin-top:8px"></div><div class="actions"><button type="button" data-act="request-bank-details" data-id="'+id+'">Send message to customer</button></div></div>';const requestButton=e.querySelector('[data-act="request-bank-details"]');if(requestButton)requestButton.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();await action('request-bank-details',id,requestButton)};return}e.innerHTML='<div class="notice"><strong>Customer bank details</strong><div class="detail-grid" style="margin-top:10px"><div class="field"><span class="label">Account holder</span><strong>'+esc(p.account_holder_name||'—')+'</strong></div><div class="field"><span class="label">Bank name</span><strong>'+esc(p.bank_name||'—')+'</strong></div><div class="field"><span class="label">Sort code</span><strong>'+esc(p.sort_code||'—')+'</strong></div><div class="field"><span class="label">Account number</span><strong>'+esc(p.account_number||'—')+'</strong></div></div></div><div class="field" style="margin-top:10px"><span class="label">Payment method</span><input id="payment-method-'+id+'" value="Bank transfer"></div><div class="field" style="margin-top:10px"><span class="label">Payment reference</span><input id="payment-ref-'+id+'" placeholder="Enter payment reference"></div><div id="payment-action-status-'+id+'" class="small" style="margin-top:8px"></div><div class="actions"><button type="button" data-act="pay" data-id="'+id+'">Confirm payment sent</button></div>';const payButton=e.querySelector('[data-act="pay"]');if(payButton)payButton.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();const status=$('payment-action-status-'+id);if(status)status.textContent='';await action('pay',id,payButton)};}catch(e){const x=$('post-inspection-payment-'+id);if(x)x.textContent=e.message||String(e)}}
async function loadPayment(id){try{const p=await rpc('subscriber_get_buying_item_payment_details',{p_buying_item_id:id});const e=$('payment-'+id);if(!e)return;if(!p.bank_details_received){e.innerHTML='<p>Customer bank details are not on record.</p><div class="notice">Ask the customer to add bank details in their portal before payment.</div>';return}e.innerHTML='<div class="notice"><div class="bank-hover" tabindex="0"><span class="bank-hover-label">Customer bank details available <span aria-hidden="true">ⓘ</span></span><div class="bank-hover-card" role="tooltip"><div class="bank-row"><span class="bank-label">Account holder</span><span class="bank-value">'+esc(p.account_holder_name||'—')+'</span></div><div class="bank-row"><span class="bank-label">Bank name</span><span class="bank-value">'+esc(p.bank_name||'—')+'</span></div><div class="bank-row"><span class="bank-label">Sort code</span><span class="bank-value">'+esc(p.sort_code||'—')+'</span></div><div class="bank-row"><span class="bank-label">Account number</span><span class="bank-value">'+esc(p.account_number||'—')+'</span></div></div></div><div class="small" style="margin-top:7px">Hover over the bank details notice to view the transfer details.</div></div><label>Payment method<input id="payment-method-'+id+'" value="Bank transfer"></label><label>Payment reference<input id="payment-ref-'+id+'" placeholder="Enter the bank transfer reference"></label><div id="payment-action-status-'+id+'" class="small" style="margin-top:8px"></div><div class="actions"><button type="button" data-act="pay" data-id="'+id+'">Confirm payment sent</button></div>';const payButton=e.querySelector('[data-act="pay"]');if(payButton)payButton.onclick=async ev=>{ev.preventDefault();ev.stopPropagation();const status=$('payment-action-status-'+id);if(status)status.textContent='';await action('pay',id,payButton)};}catch(e){const x=$('payment-'+id);if(x)x.innerHTML='<div class="notice error">'+esc(e.message||String(e))+'</div>'}}
async function shipReturn(id,b){const status=$('return-action-status-'+id);busy(b,true,'Sending tracking…');if(status)status.textContent='Sending tracking information…';try{const tracking=$('return-tracking-'+id)?.value.trim()||'';if(!tracking)throw Error('Enter the return tracking number before sending the return update.');const carrier=$('return-carrier-'+id)?.value.trim()||null;const service=$('return-service-'+id)?.value.trim()||null;const trackingUrl=$('return-tracking-url-'+id)?.value.trim()||null;const instructions=$('return-instructions-'+id)?.value.trim()||null;const result=await rpc('subscriber_publish_buying_item_return_shipping',{p_shipping_method:'subscriber_override',p_shipping_label_url:null,p_shipping_label_storage_path:null,p_shipping_qr_url:null,p_shipping_qr_storage_path:null,p_shipping_carrier:carrier,p_shipping_service:service,p_shipping_tracking_number:tracking,p_shipping_tracking_url:trackingUrl,p_shipping_instructions:instructions,p_shipping_provider:carrier,p_shipping_service_url:null});if(!result?.ok)throw Error('The return tracking update was not accepted.');if(status){status.className='small success';status.textContent='Tracking information sent to the customer.'}msg('Tracking information sent to the customer.','success');await load()}catch(e){if(status){status.className='small error';status.textContent=e.message||String(e)}msg(e.message||String(e),'error')}finally{busy(b,false)}}
document.addEventListener('click',e=>{const rsvc=e.target.closest('[data-use-return-service]');if(rsvc){e.preventDefault();const id=rsvc.dataset.id;const serviceName=rsvc.dataset.serviceName||'';$('return-carrier-'+id).value=serviceName;$('return-service-'+id).value=serviceName;msg(serviceName+' selected. Enter the tracking number after booking the return with the provider.','success');return}const rb=e.target.closest('[data-returnship]');if(rb){e.preventDefault();e.stopPropagation();shipReturn(rb.dataset.id,rb);return}const u=e.target.closest('[data-use-service]');if(u){e.preventDefault();const id=u.dataset.id;$('carrier-'+id).value=u.dataset.serviceName||'';$('service-'+id).value=u.dataset.serviceName||'';$('shipping-service-url-'+id).value=u.dataset.serviceUrl||'';msg((u.dataset.serviceName||'Shipping service')+' selected. Open the link, create the shipment, then return here to upload the label.','success');return}const b=e.target.closest('[data-ship]');if(b){e.preventDefault();shipAction(b.dataset.ship,b.dataset.id,b);return}})
$('close-detail').onclick=()=>closeDetail();
function closeDetail(){openId=null;$('detail-panel').hidden=true}
$('sign-out').onclick=()=>{if(window.tradeflowSubscriberSignOut)window.tradeflowSubscriberSignOut();else{localStorage.removeItem(SESSION_STORAGE);location.href='subscriber-login.html'}};
window.addEventListener('error',e=>{if(String(e.filename||'').includes('buying-dashboard.js'))msg('Buying controller error: '+(e.error?.message||e.message||'Unknown error'),'error')});
load();